def split_replies(apps, schema_editor):
    """Historique des commentaires (0046) ramene a deux reponses : la derniere donnee en cours (note) et celle de la
    resolution (resolution_note), pour un signalement resolu dont le dernier commentaire accompagnait la resolution."""
    ProblemReport = apps.get_model('inventory', 'ProblemReport')
    for report in ProblemReport.objects.filter(replies__isnull=False).distinct():
        replies = list(report.replies.order_by('created', 'id'))
